// Module 3 — Social Media
// Rewritten for 17-year-old first-time ICT students at Amity Tashkent.
// Plain English, short sentences, Uzbek/Tashkent scenarios, no deep jargon.
// Bloom's: Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze ·
// Q9 Evaluate · Q10 Create. Correct answer is NEVER the longest option.

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: Introduction to Social Media ───
  1: [
    { q: "What is social media, in simple words?", opts: ["Apps and websites where normal users can post things and reply to each other back", "A kind of old TV channel that plays only news programmes and nothing else for viewers", "A private library of paper books kept at home for reading quietly on the weekends", "A single government website where citizens read laws and nothing more is ever allowed"], ans: 0, why: "Social media = apps/sites where normal users post AND reply. TV only talks at you. Libraries and government sites are not two-way conversations.", bloom: "remember" },
    { q: "Which of these is NOT a social media app?", opts: ["Instagram, the app famous for photos, Reels, and Stories that disappear after a day", "TikTok, the short-video app with the famous For You page made by its algorithm", "Microsoft Excel, a spreadsheet program for tables, numbers, and formulas", "Telegram, the chat and channel app used very widely in Uzbekistan today"], ans: 2, why: "Excel is a spreadsheet tool for numbers. Instagram, TikTok, and Telegram all let users post and reply — they are social media.", bloom: "remember" },
    { q: "Why do people say social media is 'two-way,' but old TV is 'one-way'?", opts: ["TV shows are shorter than social media posts and that makes TV a one-way system always", "On TV you only watch; on social media you can post back, comment, and reply", "TV is watched in big family groups while social media is watched alone, which changes direction", "Social media always uses Wi-Fi and TV does not, which is what 'two-way' actually means in class"], ans: 1, why: "'Two-way' = both sides can send messages. You can comment, reply, or post back on social media. On TV you can only receive — no way to answer.", bloom: "understand" },
    { q: "Why is social media almost free for a small Tashkent samsa shop to use?", opts: ["Because the government of Uzbekistan pays the full bill for every small shop in Tashkent", "Because old newspaper ads became illegal and shops were forced to move to online posting", "Because Instagram workers personally visit every shop in Chorsu and create all the posts for free", "Making and posting a photo costs nothing — the shop only pays for phone internet"], ans: 3, why: "A shop just takes a photo on a phone and posts it. No printing, no newspaper space. The only cost is regular mobile internet — that's why social media works for tiny shops.", bloom: "understand" },
    { q: "You open an Instagram Story of your lunch and friends tap a heart emoji to reply. Which feature of social media is this?", opts: ["Two-way chat — you posted, they replied, and a small conversation happened right there", "A paid ad, because every Story with replies is always a paid advertisement by the cafe owner", "One-way broadcast, since only you could see the replies on your screen, not anyone else", "It is not social media at all because Stories disappear after 24 hours from your profile"], ans: 0, why: "You posted, they replied — that's two-way communication. Stories are social media even though they disappear. Nobody paid; it's a normal post.", bloom: "apply" },
    { q: "A cafe near Amity campus has no social media. How does this hurt the cafe?", opts: ["Instagram will block the cafe from ever opening an account at any time in the future", "Most students find places online — a cafe with no page is nearly invisible to them", "The government fines any business that refuses to open an Instagram or Telegram account today", "Customers cannot legally enter any cafe that does not also have a verified Instagram account"], ans: 1, why: "Most Tashkent teens find cafes through Instagram or Telegram. A cafe with no page simply doesn't show up when students scroll — nearly invisible. No law forces this; it's just where attention lives.", bloom: "apply" },
    { q: "Your uncle opens a small bakery and wants cheap feedback on his new bread. How can social media help him hear customers fast?", opts: ["He buys a big newspaper ad and waits three weeks for the printed customer reply section", "He prints paper leaflets, walks them around the whole neighbourhood, and reads every letter back", "He posts a photo of the bread and reads the comments like 'tasty!' or 'too salty' the same day", "He phones every customer one by one and writes down their answers in a paper notebook slowly"], ans: 2, why: "Post the bread → read comments the same day. No printing, no phoning. Customers tell him 'tasty' or 'too salty' for free. That's why social media is the fastest feedback tool for small shops.", bloom: "apply" },
    { q: "A student scrolls Instagram for two hours, then says 'it only felt like 10 minutes.' What is happening?", opts: ["The apps are built to keep you scrolling, so time passes quickly and you don't notice it", "The student's phone has a broken battery and the clock is running incorrectly all of the time", "Instagram secretly speeds up every phone's clock as long as the app is open on the screen", "Instagram always stops working after 10 minutes so nothing real happened in the next 110 minutes"], ans: 0, why: "Apps are designed to hold your attention — autoplay video, endless feeds, notifications. That's why two hours feel like ten. It's a feature, not a bug or a clock trick.", bloom: "analyze" },
    { q: "Your friend says: 'Everything you see on Instagram and TikTok is true — if it's online, it's real.' Evaluate.", opts: ["Fully correct — the app's owners personally check every post to be completely true before allowing it", "Not quite — anyone can post anything, true or false; always check important news before you believe it", "Fully correct — there is a global law that punishes every user who posts anything false on social media", "Fully wrong — everything on social media is always a lie and you should never believe any post you read"], ans: 1, why: "Anyone can post anything. Some posts are true, many are wrong, some are lies on purpose. The apps don't fact-check. 'All true' is naive; 'all lies' is too extreme. Check big claims with trusted sources.", bloom: "evaluate" },
    { q: "Design a simple rule for yourself: when is social media helping you, and when is it wasting your time?", opts: ["Always delete all apps — social media is never ever useful for any student learning anything at all", "Use it only in the middle of the night so nobody in your family or your class can ever see you", "If it teaches you, connects you, or helps a task — fine. If you just scroll and feel tired — stop", "Keep all apps open 24 hours a day so you never miss a single post from any friend at any time"], ans: 2, why: "A balanced rule: learning, connecting, and doing a task = good. Endless scrolling with no reason = waste. Extreme rules (delete everything / always open) don't match real life.", bloom: "create" },
  ],

  // ─── Topic 2: Types of Social Media Platforms ───
  2: [
    { q: "Which social media app is built mainly for SHORT vertical videos?", opts: ["LinkedIn, which is a professional app used for job searching and online CV profiles mostly", "YouTube, which is built for longer videos like tutorials, music clips, and TV-style shows online", "Telegram, which is a chat and channel app where most posts are plain text messages in groups", "TikTok, the app known for short vertical videos and a For You page"], ans: 3, why: "TikTok is the short-video app (usually under 60 seconds). LinkedIn is for jobs, YouTube is for longer videos, Telegram is for chat and channels.", bloom: "remember" },
    { q: "Which app is mostly used in Uzbekistan for news channels and big group chats?", opts: ["Telegram, the #1 chat app in Uzbekistan for channels and groups", "LinkedIn, an international professional network used mainly for finding jobs and sharing work updates", "Facebook, which in Uzbekistan is mostly used by adults over 30 for family photos and local groups", "Instagram, which is mostly used for photos, Reels, and Stories aimed at teens and young adults"], ans: 0, why: "Telegram dominates Uzbekistan for channels and group chats — @gazeta_uz, school groups, class groups. LinkedIn is for jobs, Facebook is for older users, Instagram is for photos.", bloom: "remember" },
    { q: "Why do the same kind of videos keep showing on your TikTok 'For You' page?", opts: ["TikTok has only a very small number of videos, so the same ones repeat again and again every hour", "The app watches what you like and finish, then shows more of the same type", "TikTok shows random videos with absolutely no pattern or personal choice involved in any way at all", "Every phone in Tashkent gets exactly the same For You page, because the city has one shared feed"], ans: 1, why: "The algorithm learns from what you watch, like, and finish. Then it shows MORE of the same. That's why your feed becomes very personal after a few days.", bloom: "understand" },
    { q: "Why doesn't a LinkedIn-style post fit on TikTok, and a TikTok dance fit on LinkedIn?", opts: ["Because TikTok and LinkedIn secretly block each other's posts when the user tries to upload them online", "Because LinkedIn bans dance videos in its rules and TikTok has a rule against any form of professional text", "Because TikTok videos are always in English and LinkedIn posts are always in Uzbek without exception", "Because the apps have different audiences and purposes — jobs vs fun short video"], ans: 3, why: "LinkedIn is for jobs (adults, serious tone). TikTok is for short fun video (teens, entertainment). Same post, wrong audience = looks boring or unprofessional. The apps don't 'block' each other.", bloom: "understand" },
    { q: "You made a 15-minute video on 'How I study for IELTS.' Which app fits best?", opts: ["TikTok, because the For You page always shows every video no matter how many minutes long it runs for", "LinkedIn, because IELTS is a school topic and LinkedIn is the right place for every school video", "Telegram channel, because most teens in Tashkent watch 15-minute videos inside Telegram channels", "YouTube, which is built for longer videos like tutorials and learning content"], ans: 3, why: "YouTube is built for longer video (5 minutes to 2 hours). TikTok cuts off short. LinkedIn is jobs, not study tutorials. Telegram channels are mostly short text and links, not 15-minute videos.", bloom: "apply" },
    { q: "A Tashkent photographer wants to show her best photos and get new clients. Which app is the best fit?", opts: ["LinkedIn, because every photographer must post her work only on LinkedIn to get any client at all today", "Instagram, the photo-first app where photographers show portfolios", "Telegram, because Telegram is the best app in the world for looking at high-quality photo portfolios", "YouTube, because YouTube channels are mainly used by photographers to display still photos in galleries"], ans: 1, why: "Instagram is the photo-first app — big clean images, easy to scroll. Photographers live on Instagram. LinkedIn works for the CV, but clients look at photos on Instagram. YouTube is for video.", bloom: "apply" },
    { q: "Your family opens a small bakery near school. Which TWO apps make the most sense for reaching young neighbours?", opts: ["Instagram + Telegram, because teens and young adults scroll these two every single day in Tashkent", "LinkedIn + X (Twitter), because X is the leading app in Uzbekistan for local food announcements today", "X + YouTube, because most teen neighbours in Tashkent only use X and YouTube to find a local bakery", "Facebook only, because Facebook is the most popular app among teens in Uzbekistan in 2026"], ans: 0, why: "Tashkent teens live on Instagram and Telegram. LinkedIn is for jobs; X is blocked in Uzbekistan; Facebook skews older. Instagram (photo of bread) + Telegram (local channel) fits exactly.", bloom: "apply" },
    { q: "A student only watches football clips on Instagram. Slowly, almost every post becomes football. What does this tell us about the algorithm?", opts: ["Instagram has a bug and shows football posts to every single user in Uzbekistan right now", "The algorithm copies what you watch, so a narrow habit makes a narrow feed", "All Instagram accounts have shown only football since 2024 because of a new rule the app made", "Football clips are the only content allowed in Uzbekistan's version of the Instagram feed today"], ans: 1, why: "The algorithm learns from what you watch and shows more of the same. Narrow watching = narrow feed. It's not a bug or a country-wide rule — it's how the app works for everyone.", bloom: "analyze" },
    { q: "Your classmate says: 'If you want to reach everyone in Tashkent, just post the same thing on every app.' Evaluate.", opts: ["Fully correct — every social media app in the world has exactly the same user base and the same behaviour", "Fully wrong — posting on any two apps at once is against the rules in every social media app today", "Not quite — each app has its own style, so the same post often looks wrong somewhere", "Fully correct — most apps show the same post the same way, and copying always works for every business"], ans: 2, why: "The idea (post everywhere) isn't wrong, but 'same post' is. A photo fits Instagram; a dance fits TikTok; a long read fits a Telegram channel. Copy-paste everywhere often looks wrong on at least one app.", bloom: "evaluate" },
    { q: "Design a simple plan: which ONE app would you pick to run a page about Tashkent metro stations, and why?", opts: ["LinkedIn, because metro stations are a professional topic and belong on LinkedIn only", "X (Twitter), because it works perfectly inside Uzbekistan with no problem for any user anywhere", "Instagram, because metro stations look great in photos and teens scroll Instagram every day", "Facebook, because teens in Uzbekistan mostly use Facebook and that is the main audience for this page"], ans: 2, why: "Metro stations are visual — photos of architecture, signs, crowds fit Instagram perfectly, and teens scroll Instagram daily. LinkedIn is jobs, X is blocked in UZ, Facebook skews older.", bloom: "create" },
  ],

  // ─── Topic 3: Social Media Management Tools ───
  3: [
    { q: "What does a social media management tool mainly do?", opts: ["It lets people post and reply on many apps from one place, faster than usual", "It writes the whole post for you automatically without any idea or input from the user ever", "It turns off your Instagram account for a week to protect your privacy and save your phone battery", "It helps you delete old posts from every app you have ever used in the last ten years of your life"], ans: 0, why: "These tools put many apps in one dashboard — write once, schedule everywhere, reply from one inbox. They don't auto-write your posts or lock your account.", bloom: "remember" },
    { q: "Which of these is a well-known scheduling tool for social media?", opts: ["Buffer, a popular scheduling tool with a free plan that works for small pages", "MS Word, a word processor used mainly for letters, essays, and school reports with formatting", "Microsoft Excel, a spreadsheet tool used mainly for numbers and formulas in business", "Adobe Photoshop, a paid image editor used mainly to fix and design photos professionally"], ans: 0, why: "Buffer is a scheduling helper. Excel is spreadsheets, Word is documents, Photoshop is image editing. Only Buffer is a social media management tool.", bloom: "remember" },
    { q: "Why is scheduling posts useful for a busy student who also runs an Instagram page?", opts: ["The tool pays the student a small amount of money every time it posts on her behalf each day", "Her posts get a special golden badge that only scheduled posts receive inside the Instagram app daily", "Scheduling makes Instagram show her posts to ten times more people than any normal post", "She writes a week of posts on Sunday, then the tool posts for her while she studies"], ans: 3, why: "Scheduling = write in one batch on Sunday, tool posts through the week. It saves time, no golden badges or free money involved. Reach is NOT boosted by scheduling.", bloom: "understand" },
    { q: "Why can't one tool schedule to every single social media app?", opts: ["Because posting to more than one app a day is against international social media law in most countries", "Each app controls what tools are allowed to connect, so not every combination works", "Because every tool is paid and the free ones have no feature to connect to more than one app ever", "Because each phone can only be linked to a single social media app at a time by any user of any age"], ans: 1, why: "Each app decides which outside tools can post for users. Not every tool fits every app. No law stops multi-posting; free plans can post to many apps, just with smaller limits.", bloom: "understand" },
    { q: "A student wants to post on her thrift-clothes Instagram every weekday at 7 p.m. but has homework. What's the smartest step?", opts: ["Set five alarms at 7 p.m. every weekday and stop her homework to post at exactly the right moment", "Ask a friend with Instagram to log in and post every weekday at 7 p.m. for the whole school year", "Use a scheduler like Buffer on Sunday to line up all 5 posts for the week", "Post everything at once on Sunday night and let Instagram spread them across the week by itself"], ans: 2, why: "Schedule all 5 posts on Sunday, tool posts daily at 7 p.m. Alarms disturb homework; sharing the password is unsafe; Instagram doesn't spread posts on its own.", bloom: "apply" },
    { q: "A nail salon posts three times in one day, then goes silent for two weeks. Which tool habit would fix this?", opts: ["Sending a notification to the salon owner every single time she is too quiet for a week", "Automatically liking every post she has ever made so that her followers come back to her page", "Using a scheduler to plan a few posts each week, so posts are steady instead of bursty", "Paying Instagram to send more customers to the salon every time she forgets to post for a few days"], ans: 2, why: "A scheduler spreads posts evenly — 2–3 per week, same times. No more 3-in-one-day-then-silence. The tool doesn't auto-like or pay Instagram for you.", bloom: "apply" },
    { q: "You run a Tashkent cafe page and get many DMs on Instagram, Facebook, and Telegram. How does a 'unified inbox' help you?", opts: ["It automatically writes a perfect reply to every customer DM without you reading any message at all", "It secretly deletes any rude message so you only see the positive reviews from happy and kind customers", "It sends all your DMs to the cafe's email address and never shows them inside the original app again", "You see all DMs in one place, so you reply faster and don't miss messages"], ans: 3, why: "A unified inbox puts DMs from every app on one screen. Fewer tabs, nothing missed. It doesn't auto-reply or secretly delete rude messages — you still read and answer.", bloom: "apply" },
    { q: "Your cousin schedules 50 posts for the whole month, then ignores every comment and DM for 4 weeks. What goes wrong?", opts: ["Followers feel ignored and stop trusting the page — replies matter, not just posts", "The scheduling tool stops working after 30 days because of its monthly connection timeout rule", "Instagram permanently deletes the page after exactly 28 days of not replying to any single comment", "The cousin pays a huge fine to Instagram because every business page must reply within an hour"], ans: 0, why: "Scheduling handles POSTS. Replies and DMs are a separate job. If you skip them, followers feel unheard and leave. No fines or 28-day deletions exist.", bloom: "analyze" },
    { q: "A friend says: 'Canva is the same thing as Buffer — any design tool is just another scheduler.' Evaluate.", opts: ["Fully correct — Canva and Buffer are different names of the same app made by one company", "Fully wrong — Canva and Buffer have absolutely no use at all for any small business or student page", "Not quite — Canva designs the picture, Buffer schedules the post; different jobs, used together", "Fully correct — both tools schedule posts, but Canva costs more money than Buffer does for every user"], ans: 2, why: "Canva = design the image. Buffer = schedule when to post. Different jobs that often work together. Not the same app, and both are useful.", bloom: "evaluate" },
    { q: "Design a simple weekly plan for a one-person Tashkent cafe page using a scheduler and a design tool.", opts: ["Post 30 times a day every day, and never reply to any customer comment or question on the page", "Sunday: design 5 posts in Canva, schedule in Buffer for weekdays at 7 p.m., reply to DMs daily", "Post only in the middle of the night when no customer is online and then ignore every reply they send", "Make one post a year on the cafe's birthday and do absolutely no other posting for the rest of the year"], ans: 1, why: "Good weekly plan: one design session, scheduled across the week, plus daily reply time. Over-posting annoys people, night-only posts miss viewers, once-a-year kills the page.", bloom: "create" },
  ],

  // ─── Topic 4: Social Media Measurement & Reporting ───
  4: [
    { q: "What does 'reach' mean on Instagram Insights, in simple words?", opts: ["How many different people saw your post", "The total number of likes, comments, shares, and saves your post received, combined in one number", "The number of times Instagram sent your post out as a push notification on someone's locked screen", "The number of followers your account has gained in the last seven days, counted once per unique user"], ans: 0, why: "Reach = how many DIFFERENT people saw it. If the same friend looks 3 times, she still counts once. Likes and follower growth are different numbers.", bloom: "remember" },
    { q: "Which action is usually the STRONGEST sign that a post was great?", opts: ["A tap on the heart (a like), which takes only half a second and is the easiest to collect of all", "A share — the person wants their friends to see it too", "A scroll past without any reaction at all, which happens many thousands of times per day", "Simply opening the app and glancing at the first post before quickly scrolling to the next one"], ans: 1, why: "Sharing = 'I want my friends to see this.' That's the strongest signal. A like is easy and cheap. Scrolling past and just opening the app are not signs of a good post at all.", bloom: "remember" },
    { q: "Why is a comment usually worth more than a like?", opts: ["Instagram pays you real money every time a user writes a comment on one of your recent public posts", "A comment takes real effort to type — it shows the post actually made someone stop and think", "Comments are counted three times by Instagram while likes are only counted a single time per viewer", "Comments are never deleted by the app but likes can disappear after about seven days of inactivity"], ans: 1, why: "A like is one tap. A comment takes effort — typing a sentence means the post made them pause. Instagram doesn't pay you per comment, and neither action is counted 3x.", bloom: "understand" },
    { q: "Why is a big jump in followers in one day NOT always a healthy sign?", opts: ["Because Instagram always charges your credit card a large fee for every new follower above 100 per day", "Because every account in the world is only allowed to gain exactly five followers per calendar day", "Because the app automatically deletes the new followers within 48 hours using a cleanup system it runs", "A huge jump often means one post went viral by luck, not that the page is growing steadily"], ans: 3, why: "A viral post can add 1,000 followers in a day — then nothing for weeks. That's luck, not steady growth. Slow and steady growth (a few a day) is healthier. No fees or limits exist.", bloom: "understand" },
    { q: "A student's baking page gets Post A: 300 likes, 3 comments; Post B: 150 likes, 80 comments and 40 saves. Which post is better?", opts: ["Post A, because it got more likes than Post B and likes are the only metric that really matters in any case", "Post B — fewer likes, but comments and saves show real people kept the recipe", "Neither post is better than the other; likes and comments always balance out to an equal score in the end", "Both posts are exactly the same because likes and comments are completely identical signals in every way"], ans: 1, why: "Post B has real conversation (80 comments) and real usefulness (40 saves) — people kept the recipe. Post A has more 'easy taps' but weaker signals. Depth beats quantity.", bloom: "apply" },
    { q: "Your friend brags: 'My page has 5,000 followers, your page has only 300.' Your 300-follower posts get 60 likes and 10 comments. Hers get 20 likes and 0 comments. Whose page is really healthier?", opts: ["Your page — smaller, but real people are liking and commenting on every single post you share", "Her page, because 5,000 followers always automatically beats 300 followers no matter what any post gets", "Both pages are equally healthy because follower count is the only important number on social media today", "Her page, because Instagram rewards accounts with more than 1,000 followers with a hidden quality boost"], ans: 0, why: "Follower count alone is a weak signal. Your 60 likes + 10 comments on 300 followers means real people care. Her 20 likes on 5,000 followers shows silent or fake followers. Engagement matters more.", bloom: "apply" },
    { q: "You post a recipe Reel and see: reach 1,200, likes 80, comments 5, saves 90. Which number tells you the recipe was really useful to people?", opts: ["Reach 1,200, which only means many scrolled past the Reel on their screens without really stopping to read", "Likes 80, because every single like on Instagram proves the user carefully read the recipe word by word", "Comments 5, because the only real sign of a useful post is how many users typed a full written comment", "Saves 90 — people bookmarked the recipe so they can cook it later"], ans: 3, why: "Saves = 'this was useful, I'll use it later.' 90 saves is the strongest signal of usefulness. Reach just counts eyeballs, likes are cheap, 5 comments is small — saves tell the real story.", bloom: "apply" },
    { q: "Your TikTok analytics show reach going UP, but comments going DOWN. What does this tell you?", opts: ["More people are seeing your videos, but fewer feel the urge to stop and say something", "Your page is about to be deleted by TikTok because reach and comments must always move together", "TikTok is broken for your account and you should delete the app and reinstall it right away now", "Nothing useful — the numbers make no sense, and you should always ignore TikTok analytics completely"], ans: 0, why: "Reach up = more eyeballs. Comments down = but fewer people are moved to reply. Maybe the videos are seen by the wrong group, or hooks are weaker. Useful signal — definitely not meaningless.", bloom: "analyze" },
    { q: "Your cousin says: 'Only follower count matters. The rest is useless.' Evaluate.", opts: ["Fully correct — big accounts always have the best posts and the most real customers in every city", "Fully wrong — nobody in the world should ever look at their follower count, it is totally useless", "Not quite — followers alone can be silent or fake; likes, comments, and saves show the real story", "Fully correct — every advertiser only pays based on follower count and no other metric exists for them"], ans: 2, why: "Followers matter a little, but silent/fake followers are worthless. Likes, comments, saves, and shares show if real people engage. A balanced view wins — extremes are wrong.", bloom: "evaluate" },
    { q: "Design a simple weekly check for your own Instagram page using only free Insights numbers.", opts: ["Check all numbers every 5 minutes on every school day to see exactly what is going on at any moment", "Never look at any numbers — just keep posting forever and hope that something good happens to the page", "Each Sunday, write reach, likes, comments, saves for the week; compare to last week's numbers", "Check follower count once a year on your birthday and completely ignore every other single number forever"], ans: 2, why: "One weekly check, compare to last week, across a few numbers (reach/likes/comments/saves) = healthy habit. Checking every 5 minutes is stressful and useless. Never checking or yearly checks miss trends.", bloom: "create" },
  ],

  // ─── Topic 5: Social Advertising ───
  5: [
    { q: "What is a social media ad, in simple words?", opts: ["A post that the shop paid the app to show to people who don't follow the shop yet", "A post that every user sees the same way at the same time, decided by government authorities online", "A post that only friends of the shop owner can see, as a personal favour from the social media app", "A post that is written by the app's own AI and then sent out to a small group of randomly picked users"], ans: 0, why: "Ad = paid post shown to non-followers the shop picks. The app labels it 'Sponsored.' Not decided by governments, not 'friends-only,' not written by the app.", bloom: "remember" },
    { q: "Which small label on Instagram tells you a post is an advertisement?", opts: ["A small 'Sponsored' label shown under the shop's name at the top of the post", "A huge red banner across the middle of every ad post saying 'ADVERTISEMENT' in block capital letters", "A paper-like sound effect that plays from your phone's speaker every single time you scroll past it today", "A long yellow warning stripe along the side of your phone screen for the whole time the ad is shown"], ans: 0, why: "Instagram shows a small 'Sponsored' under the name — easy to miss on purpose. No banners, sounds, or side stripes. That's why ads often look like normal posts.", bloom: "remember" },
    { q: "Why can a shop 'target' an ad to only 17-year-olds in Tashkent who like basketball?", opts: ["Because the government hands every shop in Uzbekistan a list of the personal details of every citizen", "Because Instagram has a public board where every user writes their age and interests in full daily", "The app already learns your age, city, and interests from what you tap — it offers that to shops", "Because the shop can somehow read your phone's camera and find basketball in your photos automatically"], ans: 2, why: "Apps quietly learn age, city, and interests from your taps, follows, and watches. They sell access to that info — shops pick filters. No public board or government lists.", bloom: "understand" },
    { q: "Why does a free post ('organic') usually reach FEWER people than a paid post?", opts: ["Free posts are always deleted by the app after exactly 12 hours, so only very few users see them", "Free posts mostly reach your followers; paid posts are pushed to many more non-followers too", "Free posts are only visible at night time while paid posts are visible during the daytime only", "Every free post ever made has to be manually approved by an Instagram moderator before it goes live"], ans: 1, why: "Free posts reach your followers and some friends-of-friends. Paid posts pay the app to push the post to many more people outside your circle. No night-only or approval rules.", bloom: "understand" },
    { q: "A small Chorsu bakery wants new customers but has a tiny budget. What is a smart first ad setting?", opts: ["Show the ad to the whole world, every country, every age, for the biggest possible reach in one week", "Target 'people in Tashkent, aged 16–45, who like food' — narrow enough to fit the bakery's real customers", "Target only people living in London who like traditional Uzbek food, because they have more money to spend", "Target nobody at all and let Facebook pick completely at random for the entire ad budget, with no rules"], ans: 1, why: "Small budget = narrow, relevant targeting. Tashkent residents who like food will actually walk in. Worldwide wastes money; Londoners can't come buy samsa; random targeting wastes every som.", bloom: "apply" },
    { q: "Your aunt's cake shop wants to start advertising but is scared of a huge bill. What feature protects her?", opts: ["Facebook's customer service phone line, which always calls back within five minutes and cancels any bill", "The app's automatic refund, which returns every single som she spent if the ad gets fewer than 10 likes", "A government rule that stops any Tashkent business from ever spending more than 5,000 som per ad total", "A daily budget — once spent, the app stops showing the ad until the next day's budget"], ans: 3, why: "A daily budget is a hard cap: once spent, ad pauses until tomorrow. No surprise bills. No government cap or automatic refund for low-performing ads exists.", bloom: "apply" },
    { q: "A Tashkent language school wants to advertise an IELTS course. Which filter combination is smartest?", opts: ["People in Tashkent, ages 16-25, who like English-learning pages", "People only in London aged 30-50, because London is the main city where IELTS students come from today", "People everywhere in the world, ages 8 to 80, with no shared interests and no language at all chosen", "People only in Samarkand who already speak fluent English and don't need any English-learning course at all"], ans: 0, why: "IELTS = students preparing for uni. Tashkent + 16–25 + likes English pages fits perfectly. Worldwide is wasteful; London targets the wrong country; Samarkand + already fluent is the opposite audience.", bloom: "apply" },
    { q: "A shop pays for ads but its photos are blurry and the cafe inside is dirty. Sales don't grow. What's the real problem?", opts: ["The ad budget is too small; paying double every single month will definitely fix the dirty cafe problem", "A paid ad can't fix a bad product — more people see the shop, but don't come back", "Instagram's algorithm secretly hides every ad from this specific shop because it doesn't like the logo colour", "The shop should switch from Instagram to LinkedIn, because LinkedIn always makes dirty cafes look cleaner"], ans: 1, why: "Ads bring eyeballs. If the photo is bad and the cafe is dirty, new customers won't come back and won't tell friends. Fix the product first. More money, different apps, or hidden algorithms won't save it.", bloom: "analyze" },
    { q: "Your friend says: 'If I see an ad, I'm smart enough to just ignore it. Ads don't work on me.' Evaluate.", opts: ["Fully correct — anyone who pays attention in class is immune to every ad ever shown on social media today", "Fully wrong — every single ad works on every user, and nobody has ever ignored any ad on any app at all", "Not quite — ads are designed by experts; they work even on people who think they are immune to them", "Fully correct — ads only ever affect very small children, so no teenager or young adult is ever persuaded by one"], ans: 2, why: "Ads are made by expert teams and run huge tests. Even people who 'ignore' ads are influenced by what they see repeatedly. Nobody is fully immune, but nobody is fully controlled either — middle answer wins.", bloom: "evaluate" },
    { q: "Design a small first ad for a new Tashkent cafe near Amity with a budget of 30,000 som for one day.", opts: ["Target people worldwide, ages 5-90, with every interest selected, and spend the whole 30,000 som on day one", "Skip social media ads entirely and put the whole 30,000 som into an expensive TV advert on Uzbek national television", "Tashkent, 16-28, likes cafes/food, 30,000 som daily cap, one bright photo of the best dessert, 'come today' text", "Target only people who already eat at the cafe every day, because they are the most reliable customer group"], ans: 2, why: "Narrow targeting (city + age + food interest), daily cap, strong photo, clear 'come today' message — classic small-budget ad. Worldwide wastes money; TV is way more expensive; existing customers already visit.", bloom: "create" },
  ],

  // ─── Topic 6: Facebook Marketing ───
  6: [
    { q: "In Uzbekistan, which age group mostly uses Facebook?", opts: ["Teens aged 13 to 17 at every school and every university in the country without any exception in 2026", "Children under 10, because Facebook is Uzbekistan's favourite app for primary-school kids today", "Nobody at all — Facebook is completely blocked inside Uzbekistan by a nationwide internet rule", "Adults over 30 — parents, teachers, and small-business owners"], ans: 3, why: "In Uzbekistan, Facebook skews older — 30+. Teens prefer Instagram and TikTok. Children don't dominate Facebook. Facebook is not blocked in Uzbekistan.", bloom: "remember" },
    { q: "What is a Facebook 'Page' (for a shop), in simple words?", opts: ["A free public profile for a business where customers can follow without becoming friends", "A paid advertisement that every Facebook user sees inside their private family chat for exactly one day", "A private chat group where only the shop owner's family and close friends are allowed to join it", "A personal profile that the shop owner uses for their own holiday photos and birthday party updates"], ans: 0, why: "A Page = free public shop profile (name, hours, photos). Anyone can follow without becoming 'friends.' Different from a personal profile, not an ad, not a family chat.", bloom: "remember" },
    { q: "Why do Instagram and Facebook feel so connected?", opts: ["Because every user in the world is required by law to use both apps at the same time every day", "Because one app copies every single post from the other app automatically, without ever telling any user", "Because they use the same logo, the same colours, and the same username rules across every country", "Because they are both owned by the same company, Meta, and share tools"], ans: 3, why: "Meta owns both. That's why you can post to BOTH at once from Meta Business Suite. They don't auto-copy posts, and they don't share usernames or logos.", bloom: "understand" },
    { q: "Why would a Tashkent home-baker still open a Facebook Page in 2026, even though teens mostly use Instagram?", opts: ["Facebook gives every home-baker in Tashkent a free monthly payment for each post they upload online", "Because the adult customers (parents, aunties) who buy the cakes are usually on Facebook", "Because Facebook is the only social media app that can show pictures of any kind of cake to users", "Because Uzbek law requires every home-baker to register a Facebook business account before selling food"], ans: 1, why: "Home-bakers sell mostly to adults (parents/aunties), and adults use Facebook in Uzbekistan. So that's where the customers are. Meta doesn't pay users to post, and no such Uzbek law exists.", bloom: "understand" },
    { q: "Your mother bakes bread for neighbours. Which platform fits her customer age best?", opts: ["TikTok, because grandmothers and mothers in Uzbekistan only find homemade bread on TikTok in 2026", "LinkedIn, because all professional home-bakers list their bread recipes on LinkedIn these days", "Facebook Page, because her customers (neighbours and aunties) are already active on Facebook", "X (Twitter), because every Tashkent mother uses X to place a daily bread order for her family today"], ans: 2, why: "Her customers are adult neighbours — mostly on Facebook in Uzbekistan. TikTok skews teen, LinkedIn is jobs, X is blocked in Uzbekistan. Facebook Page wins here.", bloom: "apply" },
    { q: "A Tashkent cafe has a good photo of its new dessert. The owner wants more adults to see it on Facebook. What's the simplest first step?", opts: ["Boost the post — pay Facebook a small amount so more adults see this one post", "Delete every old Facebook post the cafe ever made and start a brand new Facebook Page from scratch", "Pay a professional Hollywood film studio to make a 30-minute documentary about the dessert this week", "Post the photo once, then close the Facebook Page forever and ignore all comments for months"], ans: 0, why: "'Boosting' is the beginner's first ad — pay a little, one photo reaches more adults. No Hollywood needed, no need to delete and restart, no need to close the Page.", bloom: "apply" },
    { q: "You share a handmade-candle Page in a local 'Tashkent mums' Facebook group. What's the benefit?", opts: ["Facebook automatically pays you 100,000 som for every single post you make inside any local group online", "You reach thousands of local adults for free, because the group already has the right audience", "Every member of the group is forced by Facebook's rules to buy at least one candle from your shop today", "The group is only allowed to read posts in English, so nobody in Tashkent can understand your Uzbek post"], ans: 1, why: "Local groups (Tashkent mums, Chilanzar residents) already gather your target audience for free. One useful post can reach thousands of local adults. No payment to you, no forced buying, no language rule.", bloom: "apply" },
    { q: "A shop owner mixes her family photos with her cake shop posts on one profile. Why is that a problem?", opts: ["Facebook automatically deletes every personal photo uploaded to any business profile on the same day", "Customers see private family moments, the shop looks unprofessional, and privacy gets lost", "The shop's likes and comments are doubled, which makes the Page automatically banned by Facebook forever", "Every family photo counts as a paid ad, and the owner will get a huge bill from Facebook at month end"], ans: 1, why: "A Page should be separate from a personal profile. Mixing makes the shop look unprofessional and shares family info with strangers. No auto-deletion, no doubled likes, no bills for family photos.", bloom: "analyze" },
    { q: "Your friend says: 'Facebook is dead — no Tashkent business should use it in 2026.' Evaluate.", opts: ["Fully correct — every single Facebook user in Uzbekistan deleted their account at the end of 2024 already", "Fully wrong — every Tashkent business must absolutely have a Facebook Page, or they will fail at once", "Not quite — Facebook still matters for adult customers, though teens mostly live on Instagram and TikTok", "Fully correct — Meta itself closed Facebook last year and only the Instagram app is now open to Uzbek users"], ans: 2, why: "Facebook is not dead — 30+ adults, teachers, small-business owners are still there. But it's not a must-have either; teens use Instagram/TikTok. Depends on who the customers are.", bloom: "evaluate" },
    { q: "Your family plans to open a small plumbing service for Tashkent flats. Design a simple first-week Facebook plan.", opts: ["Do nothing online — just knock on every door in Tashkent one by one and introduce yourself to each flat", "Create a paid Facebook ad targeting only people in London who own a second flat somewhere in Tashkent", "Open a free Page with name, phone, address, photos, hours, then join 2 local groups and post one helpful tip", "Open twenty Pages, boost every post massively, and spend the whole family's monthly budget on ads in one day"], ans: 2, why: "Plumbing = adult customers, local = Facebook fits. Start with a free Page (basic info), join relevant local groups, share one helpful tip. Knocking door-to-door is slow; Londoners are wrong audience; 20 pages is chaos.", bloom: "create" },
  ],

  // ─── Topic 7: X (formerly Twitter) Marketing ───
  7: [
    { q: "What is X (formerly Twitter), in simple words?", opts: ["A social app mainly for very short posts, usually under 280 letters", "A long-form video platform that hosts mainly 1-hour news shows from around the world every day", "A photo-only app where every post must be a picture with no written words allowed anywhere at all", "A private messaging app used only for direct chat between two people, with no public posts ever"], ans: 0, why: "X = short public posts under 280 letters. It is NOT long video (YouTube), photo-only (Instagram), or private-only (Telegram DM). The short public post is the whole point.", bloom: "remember" },
    { q: "What is the situation with X in Uzbekistan?", opts: ["X is more popular in Uzbekistan than Telegram and Instagram combined together, with no restrictions at all", "X is blocked in Uzbekistan, so most people use Telegram channels for short news instead", "X is the only social app that works inside Uzbekistan, so every student is required to use it daily", "X has been renamed to Uzbek-X and became the government's official social app in every school building"], ans: 1, why: "X is blocked in Uzbekistan. Telegram channels fill the same 'short news updates' role. X is not more popular than Telegram in UZ, not the only app, and not a government app.", bloom: "remember" },
    { q: "Why do shops in countries where X works often answer customer complaints on X fastest?", opts: ["Because complaints on X are public — other customers see them, so the company can't quietly ignore", "Because every X message sends a loud alarm sound to every single company phone across the whole office", "Because X employees personally phone each company and read out every complaint twice, every single hour", "Because complaints on X are written in small letters and are therefore easier to read than long emails"], ans: 0, why: "X complaints are public — everyone watching. Silence looks bad, so companies reply fast. There's no alarm sound, no X staff phoning companies, and the text size isn't the point.", bloom: "understand" },
    { q: "Why is a Telegram channel in Uzbekistan seen as the local equivalent of an X account?", opts: ["Because Telegram channels are secretly owned by the same company that owns X across the world today", "Because Telegram channels have exactly 280 letters per post, just like X, and no post can be longer", "Both give short, fast updates to many followers at once and are easy to share to friends", "Because Telegram channels are only for news, while X is only for jokes and football scores across the world"], ans: 2, why: "Both push short updates to followers fast. Same JOB, different app. Telegram has no 280-letter limit, isn't owned by X, and carries much more than only news.", bloom: "understand" },
    { q: "A Tashkent bookshop wants to post a 'Book of the Week' short message every Monday. Which app fits local customers best?", opts: ["An X account, because X is the most widely used app among teenagers in Tashkent in the year 2026", "A Telegram channel, because local customers are on Telegram and X is blocked in Uzbekistan", "A LinkedIn profile, because every Tashkent bookshop customer only checks LinkedIn for book updates today", "A private WhatsApp group of all the bookshop staff's family members, and nobody from outside at all ever"], ans: 1, why: "Local customers = Telegram. X is blocked in UZ. LinkedIn is for jobs. A family WhatsApp group misses every actual customer. Telegram channel is the clear fit.", bloom: "apply" },
    { q: "Imagine you travel to London for a student event. You want quick news about flight delays. Which app fits well there?", opts: ["X, because airlines in the UK post delay updates there and many British news channels use X first", "Telegram, because every British airline and every UK news channel runs a public Telegram channel too", "LinkedIn, because flight delays are always posted on the professional LinkedIn feed of every UK airline", "Facebook Marketplace, because delay announcements are always posted inside Marketplace in every country"], ans: 0, why: "X works in the UK and is fast for live events — flight delays, breaking news, sports. Telegram is smaller in the UK, LinkedIn is jobs, Marketplace is buying/selling.", bloom: "apply" },
    { q: "You see a hashtag #Tashkent2026 under a post. What does it do?", opts: ["It is only decoration and doesn't actually do anything special on any social media app in any country today", "It makes the post's text bright yellow automatically so the eye goes to it first on every scroll through a feed", "Clicking it shows every other post using the same hashtag — a topic page made of many posts", "It sends a copy of the post to every person in Tashkent by SMS, automatically, within about 60 seconds today"], ans: 2, why: "A hashtag groups every post using it into one clickable topic page. Not decoration, not a colour change, not an SMS blast. It's a topic tag.", bloom: "apply" },
    { q: "A tourist company in Bukhara has an active X account but sees no rise in Uzbek customers. Why?", opts: ["X has zero audience in the world and no user from any country has opened the app in the year 2026 at all", "Every Uzbek user with an X account is only allowed to follow foreign celebrities and no local businesses ever", "X automatically hides every post made by Bukhara companies because of a special rule inside the app", "X is blocked in Uzbekistan, so local Uzbek customers can't easily see the company's X posts"], ans: 3, why: "X is blocked in UZ — local Uzbeks can't see X posts without a VPN. The audience is elsewhere. X is not empty worldwide, has no Bukhara rule, and no follow restrictions like that.", bloom: "analyze" },
    { q: "A classmate says: 'X is totally useless for Uzbek students — we should never learn about it.' Evaluate.", opts: ["Fully correct — students who grow up in Uzbekistan will never see an X post in their entire lifetime", "Not quite — X is blocked here, but students may travel or work abroad and will see X there", "Fully wrong — X is Uzbekistan's most popular social app by a huge margin in every single city in the country", "Fully correct — every foreign university and every foreign company banned the use of X in 2025 for good"], ans: 1, why: "X is blocked locally, but many students travel, study abroad, or work for global companies. Knowing the basics is useful. It's not Uzbekistan's top app, and foreign unis haven't banned it.", bloom: "evaluate" },
    { q: "Design a simple rule for yourself about X while you live in Uzbekistan.", opts: ["Ignore X completely forever and never learn anything about the app or how it works in any country at all", "Open a new X account every week and post every hour, even though nobody in Uzbekistan can read the post", "Spend two hours a day on X with a VPN and completely forget about Telegram for the rest of your school year", "Know the basics — tweet, retweet, hashtag — and use Telegram channels locally while you are here"], ans: 3, why: "Smart rule: learn the basics (tweet, retweet, hashtag) so you understand world news, but use Telegram locally because it works and the audience is here. Extremes (ignore / obsess) are weaker.", bloom: "create" },
  ],
};
